SELECT t.id AS doc_id, tl.id AS line_id, t.tranid, t.type, TO_CHAR(t.trandate, 'YYYY-MM-DD') AS trandate, t.status AS status_code, BUILTIN.DF(t.status) AS status, t.currency AS currency_id, BUILTIN.DF(t.currency) AS currency, t.entity AS vendor_id, BUILTIN.DF(t.entity) AS vendor, tl.quantity, tl.quantityshiprecv, tl.rate, tl.netamount, tl.location AS location_id, BUILTIN.DF(tl.location) AS location, TO_CHAR(tl.expectedreceiptdate, 'YYYY-MM-DD') AS expected_receipt, tl.isclosed FROM transaction t JOIN transactionline tl ON tl.transaction = t.id AND tl.mainline = 'F' AND tl.taxline = 'F' WHERE t.type IN ('VendBill', 'PurchOrd') AND tl.item = :item_id AND t.trandate >= TO_DATE(':from', 'YYYY-MM-DD') AND t.trandate <= TO_DATE(':to', 'YYYY-MM-DD') ORDER BY t.trandate DESC, t.id DESC, tl.id
